class TsharkMessageSource(message_source_base.MessageSource):
    '''
    Specific message source that implements extracting unparsed messages from tshark data stream
    '''

    _rrc_message_type_getter = re.compile(r'lte-rrc.c\d+.*?showname=\"c\d+\:\s(\S+)', re.MULTILINE)
    _s1x2m3ngf1e1_message_type_getter = re.compile(r'ap\.value_element\"\sshowname=\"value\".*?showname=\"(\S+)\"',
                                                   re.MULTILINE | re.DOTALL)
    _xn_message_type_getter = re.compile(r'\.value_element\"\sshowname=\"value\".*?showname=\"(\S+)\"',
                                         re.MULTILINE | re.DOTALL)
    _occurence_epoch_time_getter = re.compile(r'frame.time_epoch.*?show=\"(.*?)\"', re.MULTILINE)
    _rrc_device_id_getter = re.compile(r'{iphy_proto}\.ue_id.*?show=\"(\d+)\"'.format(iphy_proto=IPHY_PROTO_NAME), re.MULTILINE)
    _protocol_getter = re.compile(r'(\w+AP)\_PDU')

    iphy_message_type_capture_filter = "ip[38:2]"
    iphy_gtp_teid_capture_filter = 'ip[32:4]'
    iphy_fragmented_packet_filter = 'ip[6:1]'  # =0x20 - this means packet is fragmented
    iphy_packet_offset_filter = 'ip[7:1]'      # >0x0 - this is end of fragmented packet
    sctp_fragmented_chunk_flags_filter = 'sctp[14:1]'  # =0x01 - first segment / 0x02 - last segment
    # - actually this could be wrong but for the sake of compatibility - leaving it also
    sctp_fragmented_chunk_flags_filter_2 = 'sctp[13:1]'  # =0x01 - first segment / 0x02 - last segment
    iphy_DL_MCCH = '40'
    iphy_DL_BCCH_BCH = '62'
    iphy_DL_BCCH_SCH = '63'
    iphy_DL_PCCH = '64'
    iphy_DL_CCCH = '65'
    iphy_DL_DCCH = '66'
    iphy_UL_CCCH = '69'
    iphy_UL_DCCH = '70'
    iphy_DL_BCCH_SCH_BR = '129'

    class DataSource(object):
        '''
        Stores connection and has read(chunk) method
        '''
        def __init__(self, connection):
            self.connection = connection
            self.tshark_data_timeout = 0.1

        def read(self, chunk=4096 * 128):
            """
            Read and return connection data of size == chunk
            """
            chunk_buff = ""
            if self.connection.isalive():
                try:
                    while len(chunk_buff) < chunk:
                        chunk_buff += py3_string(self.connection.read_nonblocking(size=chunk, timeout=self.tshark_data_timeout))

                    return chunk_buff
                except pexpect.TIMEOUT:
                    return chunk_buff
            else:
                return None  # TODO: raise exception ConnectionClosed

    class TsharkPdmlParser(ta_pdml_parser.uesim_pdml_parser.UesimPdmlParser):
        '''
        Pdml parser derived ta_pdml_parser package. Uses different _iter_chunk method. Provides generator for packets.
        Uses semaphore for stop condition to exit generator.
        '''
        sleep_between_chunks = 0.01

        def __init__(self, stop_condition):
            self.stop_condition = stop_condition
            super(TsharkMessageSource.TsharkPdmlParser, self).__init__()

        def get_converted_msg(self, packet):
            '''
            Overidden method does not wrap in Message class.

            :param packet: tshark packet
            :return: one python message wrapped in dict class
            '''
            parsed_msgs = []
            uesim_hex_msgs = self._create_uesim_hex_msgs(packet)
            for uesim_hex_msg in uesim_hex_msgs:
                # msg_meta_data = dict()
                # last_protocol = self._parser_protocol_stack_and_return_last_definition(packet, container=msg_meta_data)
                asn_value_msg = self._convert_uesim_hex_msg2asn_value(uesim_hex_msg)
                lte_msg_payload = self._convert_asn_value2pythons_structure(asn_value_msg)
                parsed_msgs.append(lte_msg_payload)
            assert len(parsed_msgs) == 1, "More messages in one packet not supported!"
            return parsed_msgs[0]

        def iter_packets(self, pdml_source):
            '''
            Collects chunks and from tries to return as many packets as found in sum of chunks.

            :param pdml_source: source with read method
            :return: iterator
            '''

            remaining = ""
            for chunk in self._iter_chunk(pdml_source):
                remaining = "".join([remaining, chunk])
                unparsed_part_index = 0
                for match in re.finditer(r'<packet>.*?</packet>', remaining, re.DOTALL):
                    unparsed_part_index = match.end()
                    yield match.group(0)
                remaining = remaining[unparsed_part_index:]

        def _iter_chunk(self, data_source):
            '''
            Reads chunk from source if any.

            :param data_source: has read method
            :param chunk_size:
            :return: iterator
            '''
            while self.stop_condition.is_set():
                chunk = data_source.read()
                yield chunk

    def __init__(self, queue):
        super(TsharkMessageSource, self).__init__(queue)
        self.pdml_parser = TsharkMessageSource.TsharkPdmlParser(self.is_running)
        self.source_specific_parser = message_parser.TsharkMessageParser(self.pdml_parser)
        self._connection = self._get_opened_connection()
        self._data_source = TsharkMessageSource.DataSource(self._connection)
        self._start_in_separate_thread()

    def check_interface(self, if_name):
        '''
        Raises exception when interface for tshark does not exists, otherwise does nothing.

        :param if_name:
        :return:
        '''
        if str(if_name) == 'any' or message_source_base.check_if_interface_exists(if_name):
            pass
        else:
            raise InterfaceForTsharkDoesNotExist("Interface: {} does not exist".format(if_name))

    def start(self):
        '''
        Starts MessageSource infinite loop.
        Infinite loop is composed of parsing data stream, creating UnparsedMessages and sending them to the output queue
        For loop is a generator and can be broken by changed stop condition.
        '''
        self.is_running.set()
        self._source_started.release()
        self.logger.debug('{!r} thread started'.format(self))
        for unparsed_msg in self._get_unparsed_messages(None):
            self._put_to_queue(unparsed_msg)
        self._main_loop_finished.release()
        self.logger.debug('{!r} thread finished'.format(self))

    def _read(self):
        '''
        Not used in this class.
        '''
        pass

    def _get_protocol_data(self):
        '''
        Not used in this class.
        '''
        pass

    def _create_message_owner(self, tshark_packet):
        '''
        Returns owner of given type

        :param tshark_packet:
        :return: MessageOwner object instance
        '''
        device_type, device_id = self._get_message_owner_name_and_id(tshark_packet)
        create_owner_fun = getattr(self, '_create_%s_owner' % device_type.lower())
        owner = create_owner_fun(str(device_id))
        return owner

    def _create_mme_owner(self, device_id):  # TODO - should not be fixed to 'wts' on this level
        device_id = int(device_id)  # wts uses id which is integer
        return MmeIdentification.from_type_id_pairs(identifiers=[('wts', device_id)], specific_for_tool='wts')

    def _create_enb_owner(self, device_id):
        device_id = int(device_id)  # wts uses id which is integer
        return EnbIdentification.from_type_id_pairs(identifiers=[('wts', device_id)], specific_for_tool='wts')

    def _create_ue_owner(self, device_id):
        device_id = int(device_id)  # wts uses id which is integer
        return UeIdentification.from_type_id_pairs(identifiers=[('wts', device_id)], specific_for_tool='wts')

    def _get_message_owner_name_and_id(self, tshark_packet):
        if IPHY_PROTO_NAME in tshark_packet:
            return 'UE', str(self._get_ue_device_id(tshark_packet))
        elif 'S1AP_PDU' in tshark_packet or 'M3AP_PDU' in tshark_packet or 'NGAP_PDU' in tshark_packet:
            return 'MME', self._get_mme_device_id()
        elif 'X2AP_PDU' in tshark_packet or 'F1AP_PDU' in tshark_packet or 'XnAP_PDU' in tshark_packet \
                or 'E1AP_PDU' in tshark_packet:
            return 'ENB', self._get_enb_device_id()
        else:
            raise CantFindOwnerInPacket("Can't get owner info from packet")

    def _get_enb_device_id(self):
        if hasattr(self, 'id') and self.id:
            return str(self.id)
        else:
            return None

    def _get_mme_device_id(self):
        if hasattr(self, 'id') and self.id:
            return str(self.id)
        else:
            return None

    def _get_ue_device_id(self, tshark_packet):
        '''
        | matches
        |   <field name="iphy.ue_id" showname="UE Id: 169" size="2" pos="56" show="169" value="00a9"/> -> OLD
        |   <field name="proxyproto.ue_id" showname="UE Id: 169" size="2" pos="56" show="169" value="00a9"/> -> NEW

        :param tshark_packet:
        :return: id string
        '''
        if hasattr(self, 'id'):
            return str(self.id)
        else:
            return re.search(TsharkMessageSource._rrc_device_id_getter, tshark_packet).group(1)

    def _get_message_type(self, tshark_packet):
        '''
        Returns message_type of given type

        :param tshark_packet:
        :return:
        '''
        try:
            if 'iphy' in tshark_packet:
                return self._get_rrc_message_type(tshark_packet)
            elif 's1ap' in tshark_packet \
                    or 'x2ap' in tshark_packet \
                    or 'm3ap' in tshark_packet \
                    or 'ngap' in tshark_packet \
                    or 'f1ap' in tshark_packet \
                    or 'e1ap' in tshark_packet:
                return self._get_s1x2m3ngf1e1_message_type(tshark_packet)
            elif 'xnap' in tshark_packet:
                return self._get_xn_message_type(tshark_packet)
        except Exception:
            return None

    def _get_s1x2m3ngf1e1_message_type(self, tshark_packet):
        '''
        |    matches:
        |    <field name="s1ap.procedureCode" showname="procedureCode: id-InitialContextSetup (9)
        |    ...
        |    <field name="s1ap.InitialContextSetupResponse_element" showname="InitialContextSetupResponse"

        :return: capitalized first letter x2 or s1 messagetype name e.g.  InitialUEMessage
        '''
        return re.search(TsharkMessageSource._s1x2m3ngf1e1_message_type_getter, tshark_packet).group(1)

    def _get_xn_message_type(self, tshark_packet):
        '''
        |    matches:
        |    <field name="xnap_15_4_0_1906_n02.XnSetupRequest_element" showname="XnSetupRequest"

        :return: capitalized first letter xn messagetype name e.g.  XnSetupRequest
        '''
        return re.search(TsharkMessageSource._xn_message_type_getter, tshark_packet).group(1)

    def __turn_first_letter_upper(self, string):
        first = string[0]
        changed = first.upper() + string[1:]
        return changed

    def _get_rrc_message_type(self, tshark_packet):
        '''
        matches  <field name="lte-rrc.c1" showname="c1: rrcConnectionRelease (5)" size="1" pos="63" show="5" value="2e">

        :return: rrc messagetype name e.g.  rrcConnectionRelease
        '''
        return re.search(TsharkMessageSource._rrc_message_type_getter, tshark_packet).group(1)

    def __get_occurence_time(self, tshark_packet):
        '''
        matches  <field name="frame.time_epoch" showname="Epoch Time: 1466594060.935838000 seconds" size="0" pos="0" show="1466594060.935838000"/>

        :param tshark_packet:
        :return: epoch time
        '''
        return re.search(TsharkMessageSource._occurence_epoch_time_getter, tshark_packet).group(1)

    def _get_unparsed_messages(self, protocol_data):
        '''
        Returns list of unparsed_messages extracted from protocol_data (inheritance API)

        :param protocol_data: data chunks that encapsulated whole messages
        :return: list of UnparsedMessage instances
        '''
        for tshark_packet in self.pdml_parser.iter_packets(self._data_source):
            self.logger.log(core_logging.RAW_DATA, tshark_packet)
            msg_payload = tshark_packet
            (message_type, owner) = self._get_type_and_owner_from_packet(tshark_packet)
            protocol = self._get_pdu_protocol_type(tshark_packet)
            if not (message_type and owner):
                continue
            self.logger.debug('%s << Packet %s:%s arrived' % (self, str(protocol), message_type))
            occurrence_time = self.__get_occurence_time(tshark_packet)
            (msg, err, debug) = UnparsedMessage.from_asn1value_msg_type(owner=owner,
                                                                        msg_payload=msg_payload,
                                                                        message_type_value_str=message_type,
                                                                        parser=self.source_specific_parser,
                                                                        meta_data_dict={'occurrence_time': occurrence_time,
                                                                                        'protocol': protocol})
            if debug:
                self.logger.debug(debug)
            if err:
                self.logger.error(err)
                messaging_logger = logging.getLogger('messaging')
                messaging_logger.error(err)
            yield msg

    def _get_pdu_protocol_type(self, tshark_packet):
        res = TsharkMessageSource._protocol_getter.search(tshark_packet)
        if res:
            protocol = res.group(1)
        else:
            self.logger.error('%s: Could not determine protocol for packet' % self)
            protocol = None
        return protocol

    def _get_type_and_owner_from_packet(self, tshark_packet):
        try:
            owner = self._create_message_owner(tshark_packet)
        except CantFindOwnerInPacket:
            self.logger.error('%s: Tshark could not determine owner for packet: %s' % (self, tshark_packet))
            owner = None
        try:
            message_type = self._get_message_type(tshark_packet)
        except Exception:
            self.logger.error('%s: Tshark could not determine message_type for packet: %s' % (self, tshark_packet))
            message_type = None
        return message_type, owner

    @abstractproperty
    def get_tshark_command(self):
        '''
        Should be implemented by deriving class to start tshark on proper source for IPHY and EPCSIM

        You should compose it like:
        'tshark {} <remaining parameters>'.format(self.get_tshark_input_parameters())

        :return:  e.g. 'tshark -i eth4 -T pdml -Y proxyproto.ue_id' -> NEW
        '''
        pass

    def get_tshark_input_parameters(self):
        """
        tshark input may come from network interface or previosly collected .pcap file

        This method returns that part of full tshark command that is responsible for defining input of tshark process:

            Capture interface:
              -i <interface>           name or idx of interface (def: first non-loopback)
              -f <capture filter>      packet filter in libpcap filter syntax
              -s <snaplen>             packet snapshot length (def: 65535)
              -p                       don't capture in promiscuous mode
              -I                       capture in monitor mode, if available
              -B <buffer size>         size of kernel buffer (def: 2MB)
              -y <link type>           link layer type (def: first appropriate)

            Capture stop conditions:
              -c <packet count>         stop after n packets (def: infinite)
              -a <autostop cond.>  ...  duration:NUM - stop after NUM seconds
                                        filesize:NUM - stop this file after NUM KB
                                        files:NUM - stop after NUM files

            Capture output:
              -b <ringbuffer opt.> ... duration:NUM - switch to next file after NUM secs
                                       filesize:NUM - switch to next file after NUM KB
                                          files:NUM - ringbuffer: replace after NUM files
            Input file:
              -r <infile>              set the filename to read from (- to read from stdin)

        :return:  e.g. '-i eth4'
        """
        return ''

    @staticmethod
    def get_fragmented_packets_capture_filter():
        """
        Returns strings:
        ip[6:1]=0x20 or ip[7:1]>0x0
        which is accountable for selecting packets that are fragmented (first segment| middle segment) and are
        last packets in sequence (packets offset > 0)
        :return:
        """
        fragmented_packet = "{}=0x20".format(TsharkMessageSource.iphy_fragmented_packet_filter)
        last_packet_of_fragmented_package = "{}>0x0".format(TsharkMessageSource.iphy_packet_offset_filter)
        reassembly_filter = " or ".join([fragmented_packet, last_packet_of_fragmented_package])
        return reassembly_filter

    @staticmethod
    def get_sctp_fragmented_packets_capture_filter():
        """
        Returns strings:
        sctp[14:1]==0x01 or sctp[14:1]==0x02
        which is accountable for selecting packets that are fragmented within sctp (applicable for airphone or
        iphy over airscale only).
        it selects sctp data chunks with specific chunk flags:
        0x01 - first segment
        0x02 - last segment
        Legacy packets have both chunk flags set, to for legacy packet number is 0x03 (no fragmentation on sctp)
        :return:
        """
        first_segment_sctp_packet = "{}=0x01".format(TsharkMessageSource.sctp_fragmented_chunk_flags_filter)
        last_segment_sctp_packet = "{}=0x02".format(TsharkMessageSource.sctp_fragmented_chunk_flags_filter)
        first_segment_sctp_packet_2 = "{}=0x01".format(TsharkMessageSource.sctp_fragmented_chunk_flags_filter_2)
        last_segment_sctp_packet_2 = "{}=0x02".format(TsharkMessageSource.sctp_fragmented_chunk_flags_filter_2)
        reassembly_filter = " or ".join([first_segment_sctp_packet, last_segment_sctp_packet,
                                         first_segment_sctp_packet_2, last_segment_sctp_packet_2])
        return reassembly_filter

    def _get_opened_connection(self):
        '''
        Returns established connection object to data stream (inheritance API)

        :return: connection
        '''
        process = pexpect.spawn(self.get_tshark_command())
        process.expect('Capturing on')
        time.sleep(1)   # additional sleep for tshark to begin catching
        self.logger.debug('%s << started capturing tshark packets' % self)
        return process

    def _close_connection(self):
        '''
        Closes connection to data stream (inheritance API)
        '''
        self._connection.close()
        pass


class TsharkHexMessageSource(message_source_base.MessageSource):
    '''
    Specific message source that implements extracting unparsed messages from tshark hex data stream
    '''
    iphy_message_type_capture_filter = "ip[38:2]"
    iphy_message_type_sack_present_capture_filter = "ip[74:2]"
    iphy_message_type_sack_not_present_capture_filter = "ip[58:2]"
    iphy_sctp_sack_present = "ip[32:1]=0x3"
    iphy_sctp_sack_not_present = "ip[32:1]=0x0"
    iphy_gtp_teid_capture_filter = 'ip[32:4]'

    class DataSource(object):
        '''
        Stores connection and has read(chunk) method
        '''
        def __init__(self, connection):
            self.connection = connection

        def read(self, chunk=4194304):
            """
            Read and return connection data of size == chunk
            """
            if self.connection.isalive():
                try:
                    return py3_string(self.connection.read_nonblocking(size=chunk, timeout=1))
                except pexpect.TIMEOUT:
                    return ""
            else:
                return None  # TODO: raise exception ConnectionClosed

    def __init__(self, queue, owner, iphy_gtpu=True):
        super(TsharkHexMessageSource, self).__init__(queue)
        self.iphy_gtpu = iphy_gtpu
        self.unparsed_messages_generator = get_unparsed_messages_generator(self.source_description,
                                                                           stop_condition=self.is_running.is_set)
        self.owner = owner
        self.tmp_file = None
        self.source_specific_parser = message_parser.TsharkHexMessageParser(self.source_description)
        self._connection = self._get_opened_connection()
        self._data_source = TsharkHexMessageSource.DataSource(self._connection)
        self._start_in_separate_thread()

    def check_interface(self, if_name):
        '''
        Raises exception when interface for tshark does not exists, otherwise does nothing.

        :param if_name:
        :return:
        '''
        if str(if_name) == 'any' or message_source_base.check_if_interface_exists(if_name):
            pass
        else:
            raise InterfaceForTsharkDoesNotExist("Interface: {} does not exist".format(if_name))

    def start(self):
        '''
        Starts MessageSource infinite loop.
        Infinite loop is composed of parsing data stream, creating UnparsedMessages and sending them to the output queue
        For loop is a generator and can be broken by changed stop condition.
        '''
        self.is_running.set()
        self._source_started.release()
        self.logger.debug('{!r} thread started'.format(self))
        for unparsed_msg in self._get_unparsed_messages(None):
            self._put_to_queue(unparsed_msg)
        self._main_loop_finished.release()
        self.logger.debug('{!r} thread finished'.format(self))

    def _read(self):
        '''
        Not used in this class.
        '''
        pass

    def _get_protocol_data(self):
        '''
        Not used in this class.
        '''
        pass

    def _get_message_types_filter(self):
        int_types = list([x for x in list(lua_message_types.keys()) if lua_message_types[x] in self._used_message_types])
        hex_types = [hex(int_value) for int_value in int_types]
        configured_gtp_values = [self.iphy_gtpu]
        message_type_filter_list = []
        if AIRPHONE_GTPU_AND_SCTP_BOTH_ON is True:
            configured_gtp_values = [True, False]
        for gtp_value in configured_gtp_values:
            if gtp_value is False:
                capture_filter_elements_sack_present = ['{}={}'.format(
                    TsharkHexMessageSource.iphy_message_type_sack_present_capture_filter, hex_type)
                    for hex_type in hex_types]
                capture_filter_elements_sack_not_present = ['{}={}'.format(
                    TsharkHexMessageSource.iphy_message_type_sack_not_present_capture_filter, hex_type)
                    for hex_type in hex_types]
                message_type_filter_tmp = "({} and ({})) or ({} and ({}))".format(TsharkHexMessageSource.iphy_sctp_sack_present,
                                                                                  " or ".join(capture_filter_elements_sack_present),
                                                                                  TsharkHexMessageSource.iphy_sctp_sack_not_present,
                                                                                  " or ".join(capture_filter_elements_sack_not_present))
                message_type_filter_list.append(message_type_filter_tmp)

            else:
                capture_filter_elements = ['{}={}'.format(TsharkHexMessageSource.iphy_message_type_capture_filter, hex_type)
                                           for hex_type in hex_types]
                message_type_filter_tmp = " or ".join(capture_filter_elements)
                message_type_filter_list.append(message_type_filter_tmp)
        message_type_filter = " or ".join(message_type_filter_list)
        return message_type_filter

    def _get_unparsed_messages(self, protocol_data):
        '''
        Returns list of unparsed_messages extracted from protocol_data (inheritance API)

        :param protocol_data: data chunks that encapsulated whole messages
        :return: list of UnparsedMessage instances
        '''
        for packet_record in self.unparsed_messages_generator(self._data_source):
            self.logger.log(core_logging.RAW_DATA, "{} : {}".format(packet_record.type, packet_record.hex))
            message_type = packet_record.type
            owner = self._get_owner(packet_record)
            if not (message_type and owner):
                continue
            owner_log = "for {}".format(owner) if self.owner is None and owner is not None else ""
            self.logger.debug('%s << Packet %s arrived %s' % (self, message_type, owner_log))
            self.log_to_csv(packet_record.uesim_type, str(owner),
                            protocol=packet_record.protocol,
                            message_type=packet_record.type,
                            hex=packet_record.hex)
            (msg, err, debug) = UnparsedMessage.from_hexvalue_and_msg_type(owner=owner,
                                                                           data_record=packet_record,
                                                                           parser=self.source_specific_parser)
            if debug:
                self.logger.debug(debug)
            if err:
                self.logger.error(err)
                messaging_logger = logging.getLogger('messaging')
                messaging_logger.error(err)
            yield msg

    def _get_owner(self, tshark_packet):
            return self.owner

    @abstractproperty
    def get_tshark_command(self):
        '''
        Should be implemented by deriving class to start tshark on proper source for IPHY and EPCSIM

        You should compose it like:
        'tshark {} <remaining parameters>'.format(self.get_tshark_input_parameters())

        :return:  e.g. 'tshark -i eth4 -T pdml -Y proxyproto.ue_id'
        '''
        pass

    def get_tshark_input_parameters(self):
        """
        tshark input may come from network interface or previosly collected .pcap file

        This method returns that part of full tshark command that is responsible for defining input of tshark process:

            Capture interface:
              -i <interface>           name or idx of interface (def: first non-loopback)
              -f <capture filter>      packet filter in libpcap filter syntax
              -s <snaplen>             packet snapshot length (def: 65535)
              -p                       don't capture in promiscuous mode
              -I                       capture in monitor mode, if available
              -B <buffer size>         size of kernel buffer (def: 2MB)
              -y <link type>           link layer type (def: first appropriate)

            Capture stop conditions:
              -c <packet count>         stop after n packets (def: infinite)
              -a <autostop cond.>  ...  duration:NUM - stop after NUM seconds
                                        filesize:NUM - stop this file after NUM KB
                                        files:NUM - stop after NUM files

            Capture output:
              -b <ringbuffer opt.> ... duration:NUM - switch to next file after NUM secs
                                       filesize:NUM - switch to next file after NUM KB
                                          files:NUM - ringbuffer: replace after NUM files

            Input file:
              -r <infile>              set the filename to read from (- to read from stdin)

        :return:  e.g. '-i eth4'
        """
        return ''

    def _get_opened_connection(self):
        '''
        Returns established connection object to data stream (inheritance API)

        :return: connection
        '''
        tshark_cmd = self.get_tshark_command()
        process = pexpect.spawn(tshark_cmd)
        process.expect('Capturing on')
        time.sleep(1)
        self.logger.debug('%s << started capturing tshark packets' % self)
        try:
            process.expect('.pcapng', timeout=5)
            tmp_files_found = re.findall(r'\/tmp\/\S+', py3_string(process.before))
            assert len(tmp_files_found), 'Could not find tmp file in output'
            self.tmp_file = "{}.pcapng".format(tmp_files_found[0])
            self.logger.debug('Found tmp file for tshark: {}'.format(self.tmp_file))
        except pexpect.exceptions.TIMEOUT:
            self.logger.debug('Could not find .pcapng for this process')
        except AssertionError:
            self.logger.debug('Could not find tmp pcapng files in tshark output')
        return process

    def _copy_tmp_tshark_file(self):
        '''
        Copying /tmp tshark file.
        Note: Files exists only when thark is running and will be automatically deleted when it closes, so file
        must be copied before closing.
        '''
        self.logger.debug('Started copying tmp pcap file before connection closes')
        if self.tmp_file is not None:
            timestamp = datetime.datetime.today().strftime('%Y%m%d_%H%M%S')
            log_path = core_logging.get_logging_path()
            pcap_file_name = "{}_{}.pcapng".format(self._src_name(), timestamp)
            dst_path = os.path.sep.join([log_path, pcap_file_name])
            if os.path.exists(dst_path):
                cmd = 'rm -rf {}'.format(dst_path)
                self.logger.debug('Dst path: {} already exists, removing by: {}'.format(dst_path, cmd))
                os.system(cmd)
            try:
                assert os.path.exists(self.tmp_file), 'tmp file: {} not exists in filesystem'.format(self.tmp_file)
                cmd = 'cp {} {}'.format(self.tmp_file, dst_path)
                self.logger.debug('Executing cmd to copy files: {}'.format(cmd))
                os.system(cmd)
            except Exception as e:
                self.logger.debug('Could not copy tmp pcap file due to exception: {}'.format(e))
        else:
            self.logger.debug('Not found any tmp files during tshark process start')

    def _close_connection(self):
        '''
        Closes connection to data stream (inheritance API)
        '''
        try:
            self._copy_tmp_tshark_file()
        except Exception as e:
            self.logger.debug('Could not copy tshark file due to:\n{}'.format(e))
        try:
            self._connection.close()
        except pexpect.ExceptionPexpect as exc:
            tshark_pid = self._connection.pid
            tshark_process = psutil.Process(tshark_pid)
            process_status = self._get_process_status(tshark_pid)
            tshark_cmdline = tshark_process.cmdline()
            if process_status != psutil.STATUS_ZOMBIE:
                # try kill it via psutil
                self._force_retry_kill(tshark_process)
                process_status = self._get_process_status(tshark_pid)
            if process_status == psutil.STATUS_DEAD:
                pass  # done, cleaned up
            elif process_status == psutil.STATUS_ZOMBIE:
                # on some TL pexpect can't kill tshark, it remains as zombie process but it is cleanedup at next TestCase start
                print("WARN: tshark process: PID = %s, status = %s, cmd = %s" % (tshark_pid, process_status, tshark_cmdline))
            else:
                print("killing tshark process failed: PID = %s, status = %s, cmd = %s" % (tshark_pid, process_status, tshark_cmdline))
                raise exc

    def _force_retry_kill(self, tshark_process):
        tshark_process.terminate()
        gone, alive = psutil.wait_procs([tshark_process], timeout=3)
        for p in alive:
            p.kill()

    def _get_process_status(self, tshark_pid):
        try:
            tshark_process = psutil.Process(tshark_pid)
            return tshark_process.status()
        except psutil.NoSuchProcess:
            return psutil.STATUS_DEAD


class TsharkAPHexMessageSource(message_source_base.MessageSource):
    POSSIBLE_PROFILES_PATHS = [
        os.path.sep.join([os.sep, 'home', 'ute', '.config', 'wireshark'])
    ]
    PROFILE_NAME = 'ta_messaging'
    DISABLED_PROT_FILE_NAME = 'disabled_protos'
    DISABLED_PROTOCOLS = ['s1ap', 'ngap', 'm3ap', 'x2ap', 'xnap', 'e1ap', 'f1ap']
    NON_3GPP_DISSECTIONS = ['xnap', 'nokiaf1ap']
    ENABLE_NON_3GPP_DISSECTIONS = True
    REMOTE_PIPE_NAME = 'ta_messaging_tshark_pipe'
    REMOTE_PIPE_PATH = os.path.sep.join([os.sep, 'tmp', REMOTE_PIPE_NAME])
    COPY_AFTER_CONN_CLOSED_PREFIX = 'copy_after_close'
    PIPED_TSHARK_WRITE_FILENAME = '{}_'.format(COPY_AFTER_CONN_CLOSED_PREFIX) + 'ta_messaging_piped_{}.pcapng'
    PIPED_TSHARK_WRITE_FILEPATH = os.path.sep.join([os.sep, 'tmp', PIPED_TSHARK_WRITE_FILENAME])

    class DataSource(object):
        '''
        Stores connection and has read(chunk) method
        '''
        def __init__(self, connection):
            self.connection = connection

        def read(self, chunk=4194304):
            """
            Read and return connection data of size == chunk
            """
            if self.connection.isalive():
                try:
                    return py3_string(self.connection.read_nonblocking(size=chunk, timeout=1))
                except pexpect.TIMEOUT:
                    return ""
            else:
                return None  # TODO: raise exception ConnectionClosed

    def __init__(self, queue, interfaces=None, ssh_ip=None, ssh_username=None,
                 ssh_password=None, ssh_port=22, plink=False, fixed_id=None, protocol_filter=None):
        self.queue = queue
        self.interfaces = EPC_INT if interfaces is None else interfaces
        self.available_interfaces = ['any']  # self.select_available_interfaces()
        self.protocol_filter = protocol_filter
        self.fixed_protocol_name = self._get_fixed_protocol_name_from_filter(self.protocol_filter)
        super(TsharkAPHexMessageSource, self).__init__(queue=self.queue)
        self.ssh_ip = ssh_ip
        self.ssh_username = ssh_username
        self.ssh_password = ssh_password
        self.ssh_port = ssh_port
        self.plink = plink
        self.fixed_owner = fixed_id
        self._unwanted_protocols = []
        self.tmp_file = None
        self.copy_tmp_file_after_conn_closes = False
        if self.fixed_owner is None:
            self.source_description = ColumnSourceDescription(
                line_template=r'(\d+\.\d+\s+\S+\s+\S+\s+\S+\s+\S+)', separator=r"\s+",
                column_descripions=['occurrence_time', 'ip_src', 'ip_dst', 'protocol', 'hex'],
                sample_line='11.0111        10.0.1.2        10.0.1.1        18      000d40400000050000000340c34100080002')
            self.tshark_fields_definition = '-e frame.time_epoch -e ip.src -e ip.dst -e ipv6.src -e ipv6.dst -e sctp.data_payload_proto_id -e data'
        else:
            self.source_description = ColumnSourceDescription(
                line_template=r'(\d+\.\d+\s+\S+\s+\S+)', separator=r"\s+",
                column_descripions=['occurrence_time', 'protocol', 'hex'],
                sample_line='11.0111        18      000d40400000050000000340c34100080002')
            self.tshark_fields_definition = '-e frame.time_epoch -e sctp.data_payload_proto_id -e data'
        self._create_profile_if_needed()
        # self._create_pipe_for_remote_tshark()
        self._connection = self._get_opened_connection()
        self._data_source = TsharkAPHexMessageSource.DataSource(self._connection)
        self.unparsed_messages_generator = TsharkFieldParser(self.source_description,
                                                             stop_condition=self.is_running.is_set).iter_data_records
        self.source_specific_parser = message_parser.UesimHexMessageParser()
        self.setup_csv_logger()
        self._start_in_separate_thread()

    def _get_fixed_protocol_name_from_filter(self, filter):
        '''
        Return must match ap_message_type_utils.py / AP_PROTOCOL_IDS names
        '''
        if filter == 'itf_cp_cpue_cpnrt_embedded_e1ap':
            return 'E1AP'
        elif filter == 'itf_cp_cpue_cprt_embedded_f1ap':
            return 'F1AP'
        return None

    def _choose_profiles_location(self):
        for prof in TsharkAPHexMessageSource.POSSIBLE_PROFILES_PATHS:
            if os.path.exists(prof):
                return prof
        raise Exception('Profile path not found')

    @staticmethod
    def is_non_3gpp_dissections_enabled():
        """
        Check if non-3gpp dissections is enabled
        """
        return TsharkAPHexMessageSource.ENABLE_NON_3GPP_DISSECTIONS

    @staticmethod
    def get_non_3gpp_protocols_with_disabled_dissections():
        """
        Get non-standard protocol dissections like xnap_16_5_0_2103_n03
        """
        return TsharkAPHexMessageSource.NON_3GPP_DISSECTIONS

    @staticmethod
    def get_tshark_procotol_names_matching_string(matching_string):
        """
        Getting procols dissections name from tshark
        Example of tshark cmd output:
        ute@2-16-CLOUD1372:~$ tshark -G protocols | grep xnap
            NG-RAN Xn Application Protocol (XnAP)   XnAP    xnap
            NG-RAN Xn Application Protocol 16.5.0 N03 (2021-03)     XnAP_16_5_0_2103_N03   xnap_16_5_0_2103_n03

        """
        print('Executing tshark command: tshark -G protocols ')
        protocol_names = []
        try:
            tshark_output = subprocess.Popen(['tshark', '-G', 'protocols'], stdout=subprocess.PIPE,
                                             stderr=subprocess.PIPE)
            grep_output = subprocess.Popen(['grep', matching_string], stdin=tshark_output.stdout,
                                           stdout=subprocess.PIPE,
                                           stderr=subprocess.PIPE)
            out, err = grep_output.communicate()
            out = py3_string(out)
            for line in out.split('\n'):
                proto_dissector_name = str(re.split(r'\s+', line)[-1]).strip()
                if proto_dissector_name:
                    protocol_names.append(proto_dissector_name)
        except Exception as e:
            print('Exception occurred: {}, returning empty non-3gpp dissections list'.format(e))
        return protocol_names

    @staticmethod
    def get_protocols_with_disabled_dissections():
        """
        Gets all basic protocols and non-3gpp if enabled
        """
        all_disabled_protos = []
        basic_protos = copy.deepcopy(TsharkAPHexMessageSource.DISABLED_PROTOCOLS)
        all_disabled_protos.extend(basic_protos)
        if TsharkAPHexMessageSource.is_non_3gpp_dissections_enabled() is True:
            for non_3gpp_dissection in TsharkAPHexMessageSource.get_non_3gpp_protocols_with_disabled_dissections():
                non_3gpp_dissections_list = TsharkAPHexMessageSource.get_tshark_procotol_names_matching_string(non_3gpp_dissection)
                for prot in non_3gpp_dissections_list:
                    if prot not in all_disabled_protos:
                        all_disabled_protos.append(prot)
        return all_disabled_protos

    def _create_profile_if_needed(self):
        wireshark_config_path = self._choose_profiles_location()
        profile_path = os.path.sep.join([wireshark_config_path, 'profiles'])
        ta_messaging_profile = os.path.sep.join([profile_path, TsharkAPHexMessageSource.PROFILE_NAME])
        disbable_protos_path = os.path.sep.join([ta_messaging_profile, TsharkAPHexMessageSource.DISABLED_PROT_FILE_NAME])
        self._create_missing_paths_and_files(disbable_protos_path, profile_path, ta_messaging_profile)
        recreate = False
        disabled_protocol_dissections = TsharkAPHexMessageSource.get_protocols_with_disabled_dissections()
        with open(disbable_protos_path, 'r') as file:
            content = file.read()
            for prot in disabled_protocol_dissections:
                if prot not in content:
                    recreate = True
                    break
        if recreate is True:
            with open(disbable_protos_path, 'w') as file:
                for prot in disabled_protocol_dissections:
                    file.write("{}\n".format(prot))

    def _create_pipe_for_remote_tshark(self):
        """
        AP Protocol tshark will always read from real interface + this pipe to allow enabling additional mirroring
        without the need of process restart
        """
        if os.path.exists(TsharkAPHexMessageSource.REMOTE_PIPE_PATH):
            os.system('rm -rf {}'.format(TsharkAPHexMessageSource.REMOTE_PIPE_PATH))
        os.system('mkfifo {}'.format(TsharkAPHexMessageSource.REMOTE_PIPE_PATH))

    def _create_missing_paths_and_files(self, disabled_protos_path, profile_path, ta_messaging_profile):
        if not os.path.exists(profile_path):
            os.system('mkdir {}'.format(profile_path))
        if not os.path.exists(ta_messaging_profile):
            os.system('mkdir {}'.format(ta_messaging_profile))
            print('Creating file: {}'.format(disabled_protos_path))
            os.system('touch {}'.format(disabled_protos_path))
        if not os.path.exists(disabled_protos_path):
            print('Creating file: {}'.format(disabled_protos_path))
            os.system('touch {}'.format(disabled_protos_path))

    def _read(self):
        '''
        Not used in this class.
        '''
        pass

    def _get_protocol_data(self):
        '''
        Not used in this class.
        '''
        pass

    def start(self):
        '''
        Starts MessageSource infinite loop.
        Infinite loop is composed of parsing data stream, creating UnparsedMessages and sending them to the output queue
        For loop is a generator and can be broken by changed stop condition.
        '''
        self.is_running.set()
        self._source_started.release()
        self.logger.debug('{!r} thread started'.format(self))
        for unparsed_msg in self._get_unparsed_messages(None):
            self._put_to_queue(unparsed_msg)
        self._main_loop_finished.release()
        self.logger.debug('{!r} thread finished'.format(self))

    def check_interface(self, if_name):
        '''
        Raises exception when interface for tshark does not exists, otherwise does nothing.

        :param if_name:
        :return:
        '''
        if str(if_name) == 'any' or message_source_base.check_if_interface_exists(if_name):
            pass
        else:
            raise InterfaceForTsharkDoesNotExist("Interface: {} does not exist".format(if_name))

    def select_available_interfaces(self):
        '''
        Return list of available interfaces (subset of all needed interfaces list)

        :return:
        '''
        available_ifs = []
        assert isinstance(self.interfaces, list), 'Supplied interfaces must be a list'
        for if_name in self.interfaces:
            try:
                self.check_interface(if_name)
                available_ifs.append(if_name)
            except InterfaceForTsharkDoesNotExist:
                pass
        assert len(available_ifs) > 0, "No available interface to start {}".format(self.__class__.__name__)
        return available_ifs

    def _src_name(self):
        '''
        Message source name to be used for identifying it inside logs.
        Also used to construct filename of log per message source so, make it short.
        '''
        return 'sctp_gloabl_hex_spy-{}'.format("_".join(self.available_interfaces))

    def _get_supported_protocol_ids(self):
        all_ap_protocol_ids = list(AP_PROTOCOL_IDS.keys())
        syscom_specific_protocol_ids = [3840]  # corresponds to sctp==Unknow
        if not self.protocol_filter or 'itf' not in self.protocol_filter:
            for syscom_id in syscom_specific_protocol_ids:
                try:
                    all_ap_protocol_ids.remove(syscom_id)
                except Exception:
                    pass
        return all_ap_protocol_ids

    def get_tshark_command(self, piped=False):
        """
        Return tshark command string
        """
        disable_dissectors_profile = TsharkAPHexMessageSource.PROFILE_NAME
        supp_protolcols_filter = ["sctp.data_payload_proto_id=={}"
                                  .format(prot_dec_id) for prot_dec_id in self._get_supported_protocol_ids()]
        display_filter = '({}) and !(sctp.retransmission) and data'.format(" or ".join(supp_protolcols_filter))
        if self.protocol_filter:
            display_filter = '{} and {}'.format(display_filter, self.protocol_filter)
        display_filter = '"{}"'.format(display_filter)
        packets_input = self.get_tshark_input_parameters(piped)
        tshark_command = 'tshark {} -T fields {} -Y {} -C {}'.format(packets_input, self.tshark_fields_definition,
                                                                     display_filter, disable_dissectors_profile)
        print('Tshark command:\n{}'.format(tshark_command))
        return tshark_command

    def get_tshark_input_parameters(self, piped=False):
        """packets input for tshark"""
        if piped is False:
            interfaces = " ".join(["-i %s" % str(if_name) for if_name in self.available_interfaces])
            capture_filter = "sctp"
            return '-f "{}" {}'.format(capture_filter, interfaces)
        else:
            self.tmp_file = self.PIPED_TSHARK_WRITE_FILEPATH.format(time.strftime("%Y%m%d_%H%M%S"))
            self.logger.debug('Piped tshark is used, so -r option can be in use, '
                              'created tmp file for tshark: {}'.format(self.tmp_file))
            interfaces = "-r - -w {}".format(self.tmp_file)
            return interfaces
        # position of -f filter matters, if porvided before -i is defined, it applies to all interfaces
        # if given at the end, applies only to the last -i interface

    def get_remote_tshark_command(self):
        """
        Return remote tshark command string
        """
        if self.plink is True:
            tshark_command = self.get_tshark_command()
            plink_command = "plink -t -P {port} -pw {password} {username}@{ip} '{command}'".format(ip=self.ssh_ip,
                                                                                                   username=self.ssh_username,
                                                                                                   password=self.ssh_password,
                                                                                                   port=self.ssh_port,
                                                                                                   command=tshark_command)
            self.logger.debug("Creating remote tshark command: \'%s\'" % plink_command)
            return plink_command
        elif self.ssh_username == 'core':  #VRAN specific user
            vran_tl_namespace = socket.gethostname().lower()
            nwmgmt_container = 'ctr-{}-nwmgmt'.format(vran_tl_namespace)
            cpif_pod = 'ute-{}-cpif-0'.format(vran_tl_namespace)

            ssh_command = "sshpass -p {} ssh {}@{} -p {}".format(self.ssh_password, self.ssh_username, self.ssh_ip, self.ssh_port)
            kubectl_command = "kubectl exec -n {} -c {} {}".format(vran_tl_namespace, nwmgmt_container, cpif_pod)
            tcpdump_command = "tcpdump -i {} sctp -s 0 -U -n -w -".format(self.interfaces[0])
            tshark_command = self.get_tshark_command(piped=True)

            remote_command_plus_tshark_pipe = '{} "{} -- {}" | {}'.format(ssh_command, kubectl_command, tcpdump_command, tshark_command)
            print('Tshark command:\n{}'.format(remote_command_plus_tshark_pipe))
            return remote_command_plus_tshark_pipe
        else:
            tshark_command = self.get_tshark_command(piped=True)
            ssh_command = "sshpass -p {} ssh {}@{} -p {}".format(self.ssh_password, self.ssh_username, self.ssh_ip, self.ssh_port)
            tcpdump_command = "tcpdump -i {} sctp -s 0 -U -n -w -".format(self.interfaces[0])
            merged_remote_command = '{} \"{}\"'.format(ssh_command, tcpdump_command)
            merged_remote_plus_tshark_pipe = "{} | {}".format(merged_remote_command, tshark_command)
            print('Tshark command:\n{}'.format(merged_remote_plus_tshark_pipe))
            return merged_remote_plus_tshark_pipe

    def _get_opened_connection(self):
        '''
        Returns established connection object to data stream (inheritance API)

        :return: connection
        '''
        if self.ssh_ip:
            cmd_to_run_in_process = self.get_remote_tshark_command()
        else:
            cmd_to_run_in_process = self.get_tshark_command()
        if '|' not in cmd_to_run_in_process:
            process = pexpect.spawn(cmd_to_run_in_process)
        else:
            process = pexpect.spawn('/bin/bash', ['-c', cmd_to_run_in_process])
        if '-r -' in cmd_to_run_in_process:
            self.copy_tmp_file_after_conn_closes = True
            try:
                process.expect('tcpdump: listening on')
            except Exception as e:
                self.logger.error('{} << failed to start with exception: {} and out string: {}'.format(self, e, process.readlines()))
            time.sleep(1)  # additional sleep for tshark to begin catching
            self.logger.debug('%s << started capturing tshark packets via remote tcpdump' % self)
        elif ' -i ' in cmd_to_run_in_process:  # means spying on network interface
            process.expect('Capturing on')
            time.sleep(1)  # additional sleep for tshark to begin catching
            self.logger.debug('%s << started capturing tshark packets' % self)
            try:
                process.expect('.pcapng', timeout=5)
                tmp_files_found = re.findall(r'\/tmp\/\S+', py3_string(process.before))
                assert len(tmp_files_found), 'Could not find tmp file in output'
                self.tmp_file = "{}.pcapng".format(tmp_files_found[0])
                self.logger.debug('Found tmp file for tshark: {}'.format(self.tmp_file))
            except pexpect.exceptions.TIMEOUT:
                self.logger.debug('Could not find .pcapng for this process')
            except AssertionError:
                self.logger.debug('Could not find tmp pcapng files in tshark output')
        else:
            pass  # TODO: indicate what output means 'tshark really started'
            self.logger.debug('%s << started reading tshark packets' % self)
        return process

    def _log_unwanted_protocol_once(self, packet_record, exception):
        if packet_record.protocol not in self._unwanted_protocols:
            self.logger.error('[Print only once per protocol]: Could not parse message type or owner for data: {}, got exc: {}'
                              .format(packet_record, exception))
            self._unwanted_protocols.append(packet_record.protocol)

    def _extract_single_payload(self, packet_record):
        if ',' in packet_record.hex:
            return self._create_record_for_multiple_payloads_record(packet_record)
        elif ',' in packet_record.protocol:
            # may occur that tshark produces many  protocol id but one payload,
            # due to payload being reassemble from many packets
            # need to just remove one protocol
            return self._create_record_for_fragmented_record(packet_record)
        else:
            return [packet_record]

    def _create_record_for_multiple_payloads_record(self, packet_record):
        self.logger.log(core_logging.RAW_DATA, "Record with multiple payloads: {}".format(packet_record))
        hexes = packet_record.hex.split(',')
        protocols = packet_record.protocol.split(',')
        if len(hexes) == len(protocols):
            records = []
            for (hex_value, proto) in zip(hexes, protocols):
                new_values = self._create_data_for_single_record(hex_value, packet_record, proto)
                new_record = self.source_description.get_data_record(new_values)
                records.append(new_record)
            return records
        else:
            self.logger.error('Protocols not matching payloads for: {}'.format(packet_record))
            return [packet_record]

    def _create_record_for_fragmented_record(self, packet_record):
        self.logger.log(core_logging.RAW_DATA,
                        "Record with multiple protocols, reassembled from many pdus: {}".format(packet_record))
        protocols = packet_record.protocol.split(',')
        if len(set(protocols)) != 1:
            self.logger.error(
                'Protocols not matching payloads for, sigle packet reasembled from many protocols: {}'.format(
                    packet_record))
            return [packet_record]
        else:
            # all protocols assembled to single pdu
            new_values = []
            for item in self.source_description.source_column_descriptions:
                if item == 'protocol':
                    new_values.append(protocols[0])
                else:
                    new_values.append(getattr(packet_record, item))
            new_record = self.source_description.get_data_record(new_values)
            return [new_record]

    def _create_data_for_single_record(self, hex_value, packet_record, proto):
        new_values = []
        for item in self.source_description.source_column_descriptions:
            if item == 'hex':
                new_values.append(hex_value)
            elif item == 'protocol':
                new_values.append(proto)
            else:
                new_values.append(getattr(packet_record, item))
        return new_values

    def _get_unparsed_messages(self, protocol_data):
        '''
        Returns list of unparsed_messages extracted from protocol_data (inheritance API)

        :param protocol_data: data chunks that encapsulated whole messages
        :return: list of UnparsedMessage instances
        '''
        for packet_records in self.unparsed_messages_generator(self._data_source):
            self.logger.log(core_logging.RAW_DATA, packet_records)
            for packet_record in self._extract_single_payload(packet_records):
                try:
                    message_type, protocol_type = \
                        get_message_type_from_hex_and_protocol(packet_record.hex,
                                                               packet_record.protocol,
                                                               dynamic_protocol_name=self.fixed_protocol_name)
                    owner = self._get_owner(packet_record, protocol_type)
                except Exception as e:
                    self._log_unwanted_protocol_once(packet_record, e)
                    continue
                self.logger.log(core_logging.RAW_DATA, "{}:{} :: {}".format(protocol_type, message_type, packet_record.hex))
                owner_log = "for {}".format(owner)
                self.logger.debug('%s << Packet %s:%s arrived %s' % (self, protocol_type, message_type, owner_log))
                self.log_to_csv(protocol=protocol_type, message_type=message_type, hex=packet_record.hex)
                (msg, err, debug) = UnparsedMessage.ap_from_hexvalue_and_msg_type(protocol=protocol_type,
                                                                                  owner=owner,
                                                                                  message_type=message_type,
                                                                                  data_record=packet_record,
                                                                                  parser=self.source_specific_parser)
                if debug:
                    self.logger.debug(debug)
                if err:
                    self.logger.error(err)
                    messaging_logger = logging.getLogger('messaging')
                    messaging_logger.error(err)
                yield msg

    def _get_owner(self, packet_record, protocol_type):
        if self.fixed_owner is None:
            identification_type = get_identification_for_protocol(protocol_type)
            identifiers = [('ip', EndpointsIp([packet_record.ip_src, packet_record.ip_dst]))]
        else:
            identification_type = self.fixed_owner['id']
            identifiers = [('ip', EndpointsIp([self.fixed_owner['ip']]))]
        return identification_type.from_type_id_pairs(identifiers=identifiers)

    def _copy_tmp_tshark_file(self):
        '''
        Copying /tmp tshark file.
        Note: Files exists only when thark is running and will be automatically deleted when it closes, so file
        must be copied before closing.
        '''
        self.logger.debug('Started copying tmp pcap file')
        if self.tmp_file is not None:
            timestamp = datetime.datetime.today().strftime('%Y%m%d_%H%M%S')
            log_path = core_logging.get_logging_path()
            pcap_file_name = "{}_{}.pcapng".format(self._src_name(), timestamp)
            dst_path = os.path.sep.join([log_path, pcap_file_name])
            if os.path.exists(dst_path):
                cmd = 'rm -rf {}'.format(dst_path)
                self.logger.debug('Dst path: {} already exists, removing by: {}'.format(dst_path, cmd))
                os.system(cmd)
            try:
                assert os.path.exists(self.tmp_file), 'tmp file: {} not exists in filesystem'.format(self.tmp_file)
                cmd = 'cp {} {}'.format(self.tmp_file, dst_path)
                self.logger.debug('Executing cmd to copy files: {}'.format(cmd))
                os.system(cmd)
            except Exception as e:
                self.logger.debug('Could not copy tmp pcap file due to exception: {}'.format(e))
        else:
            self.logger.debug('Not found any tmp files during tshark process start')

    def _close_connection(self):
        '''
        Closes connection to data stream (inheritance API)
        '''
        if self.copy_tmp_file_after_conn_closes is False:
            try:
                self.logger.debug('Trying to copy tmp file (if any) BEFORE tshark ends')
                self._copy_tmp_tshark_file()
            except Exception as e:
                self.logger.debug('Could not copy tshark file due to:\n{}'.format(e))
        try:
            self._connection.close()
        except pexpect.ExceptionPexpect as exc:
            tshark_pid = self._connection.pid
            tshark_process = psutil.Process(tshark_pid)
            process_status = self._get_process_status(tshark_pid)
            tshark_cmdline = tshark_process.cmdline()
            if process_status != psutil.STATUS_ZOMBIE:
                # try kill it via psutil
                self._force_retry_kill(tshark_process)
                process_status = self._get_process_status(tshark_pid)
            if process_status == psutil.STATUS_DEAD:
                pass  # done, cleaned up
            elif process_status == psutil.STATUS_ZOMBIE:
                # on some TL pexpect can't kill tshark, it remains as zombie process but it is cleanedup at next TestCase start
                print("WARN: tshark process: PID = %s, status = %s, cmd = %s" % (tshark_pid, process_status, tshark_cmdline))
            else:
                print("killing tshark process failed: PID = %s, status = %s, cmd = %s" % (tshark_pid, process_status, tshark_cmdline))
                raise exc
        if self.copy_tmp_file_after_conn_closes is True:
            try:
                self.logger.debug('Trying to copy tmp file (if any) AFTER tshark ends')
                self._copy_tmp_tshark_file()
            except Exception as e:
                self.logger.debug('Could not copy tshark file due to:\n{}'.format(e))

    def _force_retry_kill(self, tshark_process):
        tshark_process.terminate()
        gone, alive = psutil.wait_procs([tshark_process], timeout=3)
        for p in alive:
            p.kill()

    def _get_process_status(self, tshark_pid):
        try:
            tshark_process = psutil.Process(tshark_pid)
            return tshark_process.status()
        except psutil.NoSuchProcess:
            return psutil.STATUS_DEAD


class Tshark5GInternalApHexMessageSource(TsharkAPHexMessageSource):
    ASIK_BIND_SSH_PORT = 8989
    ASIK_FCT_SLAVE_IPV6_ADDR_LEFT = 'fd5f:4268:2387:a881:40:43ff:fe80:20'

    def __init__(self, queue, interfaces=None, user=None, password=None, device_id=None, protocol_filter=None):
        print(device_id)
        if 'platform' in device_id and str(device_id['platform']).upper() == 'ASIK':
            self.slave_binding_process = self._bind_asik_slave_to_local_address(password=password, user=user)
            ssh_ip = 'localhost'
            ssh_port = Tshark5GInternalApHexMessageSource.ASIK_BIND_SSH_PORT
        elif 'platform' in device_id and str(device_id['platform']).upper() == 'VRAN':
            self.slave_binding_process = None
            ssh_ip = self._get_cu_master_ip()
            ssh_port = 22
        else:
            self.slave_binding_process = None
            ssh_ip = device_id['ip']
            ssh_port = 22

        super(Tshark5GInternalApHexMessageSource, self).__init__(queue, interfaces=interfaces, ssh_ip=ssh_ip, ssh_username=user,
                                                                 ssh_password=password, ssh_port=ssh_port, plink=False,
                                                                 fixed_id=device_id,
                                                                 protocol_filter=protocol_filter)

    def _get_asik_slave_local_address(self, password=None, user=None, ip=None):
        """
        sshpass -p {} 2>/dev/null ssh toor4nsn@192.168.255.1 "backplane-ip FCT -6 -c 1"
        """
        user = 'toor4nsn' if user is None else user
        password = 'oZPS0POrRieRtu' if password is None else password
        ip = '192.168.255.1' if ip is None else ip
        command = 'sshpass -p {} ssh {}@{} "backplane-ip FCT -6 -c 1"'.format(password, user, ip)
        proc = pexpect.spawn(command)
        proc.expect(pexpect.EOF)
        try:
            asik_slave_ip = re.findall(r'(\S+(?:\:\S+)+)', proc.before)[0]
        except Exception as e:
            self.logger.warn('Could not ASIK SLAVE ip from gNB by ssh: {}, error occured: {},'
                             ' returning default left address'.format(proc.before, str(e)))
            asik_slave_ip = Tshark5GInternalApHexMessageSource.ASIK_FCT_SLAVE_IPV6_ADDR_LEFT
        return asik_slave_ip

    def _bind_asik_slave_to_local_address(self, password=None, user=None, ip=None):
        """
        sshpass -p {} ssh '
                '-q -o StrictHostKeyChecking=no -o GlobalKnownHostsFile=/dev/null -o UserKnownHostsFile=/dev/null '
                '{}@{} -T -L 8989:[fd5f:4268:2387:a881:40:43ff:fe80:20]:22
        """
        user = 'toor4nsn' if user is None else user
        password = 'oZPS0POrRieRtu' if password is None else password
        ip = '192.168.255.1' if ip is None else ip
        command = 'sshpass -p {} ssh {}@{} -T -L {}:[{}]:22'\
            .format(password, user, ip, Tshark5GInternalApHexMessageSource.ASIK_BIND_SSH_PORT,
                    self._get_asik_slave_local_address())
        proc = pexpect.spawn(command)
        time.sleep(2)
        return proc

    def _get_cu_master_ip(self):
        vran_tl_dir_name = socket.gethostname().replace("-", "_")
        testline_repository_path = "/home/ute/testline_configuration"
        vran_tl_config_path = os.path.join(testline_repository_path, vran_tl_dir_name)

        if not os.path.exists(testline_repository_path):
            raise Exception("Testline configuration repository '{}' not found".format(testline_repository_path))
        if not os.path.exists(vran_tl_config_path):
            raise Exception("VRAN TL config file '{}' not found".format(vran_tl_config_path))
        try:
            sys.path.append(testline_repository_path)
            # importlib is used because module name 'vran_tl_dir_name' starts with numbers, e.g: 7_7_CLOUD5G...
            init_py_tl_variables = importlib.import_module(vran_tl_dir_name)
            if not hasattr(init_py_tl_variables, '_vcu_k8s_connection_details'):
                raise Exception("'_vcu_k8s_connection_details' not found in VRAN TL config")
            cu_master_ip = init_py_tl_variables._vcu_k8s_connection_details.ip_addr
        finally:
            sys.path.remove(testline_repository_path)

        print("CU master IP: {}".format(cu_master_ip))
        return cu_master_ip

    def _src_name(self):
        '''
        Message source name to be used for identifying it inside logs.
        Also used to construct filename of log per message source so, make it short.
        '''
        base_name = 'sctp_hex_5g_internal-{}'.format("_".join(self.interfaces))
        if self.protocol_filter is not None:
            base_name = "{}_{}".format(base_name, re.sub(r'\s+', '_', self.protocol_filter))
        return base_name

    def _close_connection(self):
        super(Tshark5GInternalApHexMessageSource, self)._close_connection()
        if self.slave_binding_process is not None:
            self.slave_binding_process.close(force=True)


class BroadcastMulticastIPHYHexMessageSource(TsharkHexMessageSource):
    '''
    Uses TsharkMessageSource as base and adds id and proper tshark command for start
    '''

    def __init__(self, queue, enb_id, cell_id):
        self._source_specific_protocol = 'lte_rrc'
        self.enb_id = enb_id
        self.cell_id = cell_id
        self.interface = 'eth4'
        self._used_message_types = list([x for x in list(lua_message_types.values())
                                         if re.search(r'MCCH$', x) or re.search(r'\_BCCH', x) or 'PCCH' in x])
        self.source_description = CELL_HEX_SOURCE
        self.tshark_fields_definition = CELL_TSHARK_FIELDS_DEFINITION
        super(BroadcastMulticastIPHYHexMessageSource, self).__init__(queue, self._create_owner())

    def _create_owner(self):
        wts_cell_id = {'enb_id': str(self.enb_id), 'cell_id': str(self.cell_id)}
        cell_identification = CellIdentification.from_type_id_pairs(identifiers=[('wts', wts_cell_id)], specific_for_tool='wts')
        return cell_identification

    def _src_name(self):
        '''
        Message source name to be used for identifying it inside logs.
        Also used to construct filename of log per message source so, make it short.
        '''
        return 'iphy-bcast-mcast-hex-%s-enb_%s-cell_%s' % (self.interface, self.enb_id, self.cell_id)

    def get_tshark_command(self):
        """
        Return tshark command string
        """
        packets_input = self.get_tshark_input_parameters()
        tshark_command = 'tshark {} -T fields {}'.format(packets_input, self.tshark_fields_definition)
        print('Tshark command:\n{}'.format(tshark_command))
        return tshark_command

    def get_tshark_input_parameters(self):
        """packets input for tshark"""
        cell_identifier_filter = ("{}={} or {}={}".format(TsharkHexMessageSource.iphy_gtp_teid_capture_filter,
                                                          _create_tshark_gtpteid_from_ids(self.enb_id, self.cell_id),
                                                          TsharkHexMessageSource.iphy_gtp_teid_capture_filter,
                                                          _calculate_teid_for_uplane_gteid_for_uec_enb_cell(cell=self.cell_id, enb=self.enb_id)))
        _message_type_filter = '({})'.format(self._get_message_types_filter())
