class IPHYHexMessageSource(TsharkHexMessageSource):
    '''
    Uses TsharkMessageSource as base and adds id and proper tshark command for start
    '''

    def __init__(self, queue, id=None):
        self.id = id
        self.interface = IPHY_INT
        for interface in self.interface:
            self.check_interface(interface)
        self._source_specific_protocol = 'lte_rrc'
        self._used_message_types = list([x for x in list(lua_message_types.values()) if re.search(r'[DC]CCH($|\_)', x)])
        self.source_description = UE_HEX_SOURCE
        self.tshark_fields_definition = UE_TSHARK_FIELDS_DEFINITION
        super(IPHYHexMessageSource, self).__init__(queue=queue, owner=self._create_owner(), iphy_gtpu=True)
        self.setup_csv_logger('uesim_type', 'owner')

    def _create_owner(self):
        return UeIdentification.from_type_id_pairs(identifiers=[('wts', int(self.id))], specific_for_tool='wts')  # iphy only uses id which is integer

    def _src_name(self):
        '''
        Message source name to be used for identifying it inside logs.
        Also used to construct filename of log per message source so, make it short.
        '''
        if self.id:
            return 'iphy_hex-{}-ue_id_{}'.format("_".join(self.interface), self.id)
        return 'iphy_hex-{}-ues'.format("_".join(self.interface))

    def get_tshark_command(self):
        """
        Return tshark command string
        """
        if self.id:
            id = "==%s" % self.id
        else:
            id = ""

        display_filter = self._source_specific_protocol + " and {iphy_proto}.ue_id".format(iphy_proto=IPHY_PROTO_NAME) + id
        packets_input = self.get_tshark_input_parameters()
        tshark_command = 'tshark {} -T fields {} -Y "{}"'.format(packets_input, self.tshark_fields_definition, display_filter)
        print('Tshark command:\n{}'.format(tshark_command))
        return tshark_command

    def _get_capture_filter(self):
        message_type_filter = self._get_message_types_filter()
        reassembly_filter = TsharkMessageSource.get_fragmented_packets_capture_filter()
        return " or ".join([message_type_filter, reassembly_filter])

    def get_tshark_input_parameters(self):
        """packets input for tshark"""
        capture_filter = '({})'.format(self._get_capture_filter())
        interfaces = " ".join(["-i {} ".format(i) for i in self.interface])
        return '{} -B 20 -f "{}"'.format(interfaces.strip(), capture_filter)


