class X2RealEnbMessageSource(TsharkMessageSource):
    '''
    Uses TsharkMessageSource as base and adds ip and proper tshark command for start
    '''
    # TO DO   How to choose between  interfaces based on user create enb alias input ?
    def __init__(self, queue, id=None, ip=None, protocol='x2ap'):
        self.ip = ip
        self.id = id
        self.protocol = protocol
        self.interface = 'eth1'
        self.check_interface(self.interface)
        super(X2RealEnbMessageSource, self).__init__(queue)
        X2RealEnbMessageSource.enable_ip_capturing_via_admin(self.interface)

    @staticmethod
    def enable_ip_capturing_via_admin(interface='eth1'):
        """
        Enables X2 messages capture by enabling IP streaming from eNB1 via LMP port
        """
        mac_add = _get_mac_address_of_interface(interface)
        robot_logger.info('Enabling ip capturing via admin and continue when already enabled')
        start_time = time.time()
        result = _change_mirroring_on_ute_admin(enable=True, mac_address=mac_add, raise_on_failure=False)
        stop_time = time.time()
        elapsed = int((stop_time - start_time))
        if result is None:
            robot_logger.info('Ip capturing enabled successfully, took {}s'.format(elapsed))
        else:
            robot_logger.info('Ip capturing enabling failed with exception: {}, took {}s,'
                              ' continue assuming mirroring is already enabled'.format(str(result), elapsed))

    def _src_name(self):
        '''
        Message source name to be used for identifying it inside logs.
        Also used to construct filename of log per message source so, make it short.
        '''
        if self.ip:
            return 'realenb-%s-%s' % (self.interface, self.ip)
        return 'realenb-%s-sctp' % self.interface

    def _create_enb_owner(self, device_id):
        return EnbIdentification.from_type_id_pairs(identifiers=[('real', device_id)], specific_for_tool='real')

    def get_tshark_command(self):
        """
        Return tshark command string
        """
        if self.ip:
            display_filter = '"%s && (ip.src==%s || ip.dst==%s) && !(sctp.retransmission)"' % (self.protocol, self.ip, self.ip)
        else:
            display_filter = "%s" % str(self.protocol)
        packets_input = self.get_tshark_input_parameters()
        tshark_command = 'tshark {} -T pdml -Y {}'.format(packets_input, display_filter)
        print('Tshark command:\n{}'.format(tshark_command))
        return tshark_command

    def get_tshark_input_parameters(self):
        """packets input for tshark"""
        capture_filter = 'sctp'
        return '-i {} -f "{}"'.format(self.interface, capture_filter)

    def stop(self):
        """
        Overides base stop, adds stop ip capture streaming at the end.
        """
        super(X2RealEnbMessageSource, self).stop()
        self.logger.info('Disabling ip capturing via ute_admin')
        start_time = time.time()
        result = _change_mirroring_on_ute_admin(enable=False, timeout=30)
        stop_time = time.time()
        elapsed = int((stop_time - start_time))
        if result is None:
            self.logger.info('Ip capturing disabled successfully, took {}s'.format(elapsed))
        else:
            self.logger.info('Ip capturing disabling failed with exception: {}, took {}s,'
                             ' continue assuming mirroring is already disabled'.format(str(result), elapsed))


class EnbBackhaulMessageSource(TsharkMessageSource):
    """
    Uses TsharkMessageSource as base. Source is collecting enb backhaul packets, mirrored to remote UNIX machine.
    """
    def __init__(self, queue, id=None, ip=None, remote_ip=None, remote_user='ute', remote_pass='emssim4Nokia#', protocol=None, interface='eth1'):
        self.interface = interface
        self.remote_user = remote_user
        self.remote_pass = remote_pass
        self.remote_ip = remote_ip
        self.enb_ip = ip
        self.id = id
        self.capture_protocol = 'sctp'
        self.protocol = protocol if protocol else ['s1ap', 'x2ap', 'm3ap']
        # self.protocol = ['s1ap', 'x2ap', 'm3ap']
        self.ssh_port = '22'
        self._fix_key_not_cached_error()
        super(EnbBackhaulMessageSource, self).__init__(queue)

    def _fix_key_not_cached_error(self):
        command = "echo 'y' | plink -t -pw %s %s@%s 'exit'" % (self.remote_pass, self.remote_user, self.remote_ip)
        robot_logger.debug("Fixing potential error with key not cached using command: \'%s\'" % command)
        p = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True)
        std_out, std_error = p.communicate()
        robot_logger.trace("Command [%s] executed. With: \nOutput:%s \nErrors: %s'" % (command, std_out, std_error))

    def _src_name(self):
        '''
        Message source name to be used for identifying it inside logs.
        Also used to construct filename of log per message source so, make it short.
        '''
        if self.enb_ip:
            return 'enb-backhaul-enb-%s' % self.enb_ip
        return 'enb-backhaul-sniffed-on-%s' % self.remote_ip

    def _create_enb_owner(self, device_id):
        return EnbIdentification.from_type_id_pairs(identifiers=[('enb_backhaul', device_id)], specific_for_tool='enb_backhaul')

    def get_tshark_command(self):
        """
        Return tshark command string
        """
        display_protocol = "||".join(self.protocol)

        if self.enb_ip:
            ip_filter = _create_tshark_bidirectional_address_filter(self.enb_ip)
            display_filter = '({}) && !(sctp.retransmission) && !(tcp.port=={}) && ({})'.format(ip_filter,
                                                                                                self.ssh_port,
                                                                                                display_protocol)
        else:
            display_filter = '!(sctp.retransmission) && !(tcp.port=={})) && ({})'.format(self.ssh_port,
                                                                                         display_protocol)
        packets_input = self.get_tshark_input_parameters()
        tshark_command = 'tshark {} -l -T pdml -Y "{}"'.format(packets_input, display_filter)
        print('Tshark command:\n{}'.format(tshark_command))
        return tshark_command

    def get_tshark_input_parameters(self):
        """packets input for tshark"""
        capture_filter = self.capture_protocol
        return '-i {} -B 50 -f "{}"'.format(self.interface, capture_filter)

    def _get_plink_command(self):
        tshark_command = self.get_tshark_command()
        plink_command = 'plink -t -pw %s %s@%s \'%s\'' % (self.remote_pass, self.remote_user, self.remote_ip, tshark_command)
        self.logger.debug("Creating plink command: \'%s\'" % plink_command)
        return plink_command

    def _get_message_owner_name_and_id(self, tshark_packet):
        if 's1ap' in tshark_packet or 'x2ap' in tshark_packet or 'm3ap' in tshark_packet:
            return 'ENB', self._get_enb_device_id()
        else:
            raise CantFindOwnerInPacket("Can't get owner info from packet")

    def _get_opened_connection(self):
        '''
        Returns established connection object to data stream (inheritance API)

        :return: connection
        '''
        process = pexpect.spawn(self._get_plink_command())
        process.expect('Capturing on')
        time.sleep(3)  # additional sleep for tshark to begin catching
        self.logger.info('%s << started capturing tshark packets' % self)
        return process

    def _close_connection(self):
        '''
        Closes connection to data stream (inheritance API)
        '''
        self._connection.close()
        pass


def _create_tshark_gtpteid_from_ids(enb, cell, uec=1):
    """
        #define GTPU_GET_UEC_TEID(uec_id, enb_id, cell_id)
        uint32_t(gtpu::UEC_TEID_BASE
        + uint32_t(uec_id - 1) * SIM_MAX_ENB_QTY * SIM_MAX_CELL_PER_ENB_QTY
        + uint32_t(enb_id) * SIM_MAX_CELL_PER_ENB_QTY
        + uint32_t(cell_id - 1))
    """
    assert (int(cell) <= SIM_MAX_CELL_PER_ENB_QTY and int(enb) <= SIM_MAX_ENB_QTY and int(uec) <= SIM_MAX_UEC_QTY), \
        'Too big values, max for uec/enb/cell: {},{},{}'.format(SIM_MAX_UEC_QTY, SIM_MAX_ENB_QTY, SIM_MAX_CELL_PER_ENB_QTY)
    int_result = (UEC_TEID_BASE +
                  (int(uec) - 1) * SIM_MAX_ENB_QTY * SIM_MAX_CELL_PER_ENB_QTY +
                  int(enb) * SIM_MAX_CELL_PER_ENB_QTY +
                  int(cell) - 1)
    hex_result = hex(int_result)
    return hex_result


def _calculate_teid_for_uplane_gteid_for_uec_enb_cell(cell, enb=1, uec=1):
    """
    Returns gtp.teid hex for iphy broadcast
    :param cell:
    :param enb:
    :param uec:
    :return: hex e.g. 0x1111
    According to:
        #define GTPU_GET_UEC_UPLANE_TEID(uec_id, enb_id, cell_id) \
        uint32_t(gtpu::UEC_UPLANE_TEID_BASE \
        + uint32_t(uec_id - 1) * SIM_MAX_ENB_QTY * SIM_MAX_CELL_PER_ENB_QTY \
        + uint32_t(enb_id) * SIM_MAX_CELL_PER_ENB_QTY \
        + uint32_t(cell_id - 1))
    """
    assert (int(cell) <= SIM_MAX_CELL_PER_ENB_QTY and int(enb) <= SIM_MAX_ENB_QTY and int(uec) <= SIM_MAX_UEC_QTY),\
        'Too big values, max for uec/enb/cell: {},{},{}'.format(SIM_MAX_UEC_QTY, SIM_MAX_ENB_QTY, SIM_MAX_CELL_PER_ENB_QTY)
    base = UEC_UPLANE_TEID_BASE
    int_result = (int(base) +
                  (int(uec) - 1) * SIM_MAX_ENB_QTY * SIM_MAX_CELL_PER_ENB_QTY +
                  int(enb) * SIM_MAX_CELL_PER_ENB_QTY +
                  int(cell) - 1)
    hex_result = hex(int_result)
    return hex_result


def _create_tshark_bidirectional_address_filter(ip):
    ip_field_name = 'ipv6' if message_source_base._is_address_ipv6(ip) else 'ip'
    filter_name = '{}.src=={} || {}.dst=={}'.format(ip_field_name, ip, ip_field_name, ip)
    return filter_name


def _get_mac_address_of_interface(interface):
    return py3_string(subprocess.check_output("cat /sys/class/net/{}/address".format(interface), shell=True)).strip()


def _change_mirroring_on_ute_admin(enable, mac_address=None, raise_on_failure=False, timeout=90):
    from taf.sbts.oam.coam.admin import admin as admin_class
    assert enable in [True, False], 'Enable parameter must be boolean'
    assert (enable is True and mac_address is not None) or enable is False, 'When enabling, macadress must be provided'
    alias = 'ta_messaging_ip_capturing'
    admin = admin_class()
    admin.setup_admin(alias=alias)
    command_factory = {
        True: {'command': 'start_ip_capture_streaming', 'args': {'measurement_point': 'NE_Terminated',
                                                                  'uplane_capturing': True,
                                                                 'dst_mac_addr': mac_address,
                                                                 'egress_port_dn':
                                                                     '/MRBTS-1/TNLSVC-1/TNL-1/ETHSVC-1/ETHLK-1',
                                                                 'alias': alias,
                                                                 'timeout': timeout}
               },
        False: {'command': 'stop_ip_capture_streaming', 'args': {'alias': alias, 'timeout': timeout}}}
    try:
        command = admin.__getattribute__(command_factory[enable]['command'])
        command(**command_factory[enable]['args'])
        return None
    except Exception as e:
        if raise_on_failure is True:
            raise e
        else:
            return e
    finally:
        admin.teardown_admin(alias=alias)


